def handle(app, svc):
    resp = svc.apply(app)
    # API v2 response: {"api_version": 2, "result": {"outcome": ..., "credit_limit": int}}
    # Fall back to v1 shape if ever returned.
    if "result" in resp:
        outcome = resp["result"].get("outcome")
        credit_limit = resp["result"].get("credit_limit", 0)
    else:
        outcome = resp.get("decision")
        credit_limit = resp.get("limit", 0)

    # Normalize outcome to canonical tokens.
    if outcome in ("declined", "decline"):
        # A decline stays a decline (network referral rule does not override decline).
        return {"action": "decline", "limit": 0}
    if outcome in ("manual_review", "refer"):
        # Not decided -> manual review queue; do not decline.
        return {"action": "queue_review", "limit": 0}
    if outcome in ("approved", "approve"):
        # Network referral rule: self_employed + requested_limit > 7000 -> queue_review.
        if app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 7000:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": int(credit_limit)}
    # Unknown outcome -> be safe, send to manual review.
    return {"action": "queue_review", "limit": 0}

